import random

class _Rules(Rules):
    def filter_observation(self, obs, env_state):
        data = obs.data
        cmds = data.get("admissible_commands")
        if not isinstance(cmds, list) or not cmds:
            return obs

        # Occasionally hide the single most "advancing" navigation command
        # (a 'go to ...' or 'clean ...' or 'put ...' command) to force the
        # policy to recover via 'look' / re-derive. Keep it narrow and
        # solvable: only drop ONE command, never the whole list.
        state = env_state.extras
        if "rng" not in state:
            state["rng"] = random.Random(env_state.step_count * 7919 + 17)

        rng = state["rng"]
        if rng.random() > 0.35:
            return obs

        # Prefer hiding a non-examine, non-help, non-look, non-inventory
        # command (i.e., an action that changes state).
        candidates = [
            c for c in cmds
            if not c.startswith(("examine", "help", "inventory", "look"))
        ]
        if not candidates:
            return obs

        hidden = rng.choice(candidates)
        new_cmds = [c for c in cmds if c != hidden]

        # Keep at least a few commands so the task stays solvable.
        if len(new_cmds) < 3:
            return obs

        return Observation(
            text=obs.text,
            data={**data, "admissible_commands": new_cmds},
        )

