class _Rules(Rules):
    def filter_observation(self, obs, env_state):
        # Subtle O-axis: occasionally remove one admissible command that is
        # NOT currently the only path to progress. This forces the policy to
        # re-derive a viable action rather than blindly following the list,
        # while keeping the task solvable (we never strip all candidates).
        cmds = obs.data.get("admissible_commands")
        if not isinstance(cmds, list) or len(cmds) < 3:
            return obs
        # Only perturb occasionally (roughly half the steps) to avoid a
        # fully predictable environment.
        if env_state.step_count % 2 == 0:
            return obs
        # Never strip commands containing goal-critical verbs.
        critical = ("cool", "put", "take", "open", "close", "go to fridge", "go to diningtable")
        safe = [c for c in cmds if not any(v in c for v in critical)]
        if not safe:
            return obs
        # Drop the first non-critical command.
        new_cmds = [c for c in cmds if c != safe[0]]
        new_data = {**obs.data, "admissible_commands": new_cmds}
        return Observation(text=obs.text, data=new_data)

class _Rules(Rules):
    def modify_transition(self, action, raw_response, env_state):
        # Inject a transient failure on the first "go to" action after the
        # Policy has picked up an object (i.e. mid-trajectory), forcing a
        # recovery. Keeps surface presentation identical; only the result
        # payload is perturbed so the Policy sees "Nothing happens" once.
        if action.name != "do":
            return raw_response
        cmd = action.kwargs.get("text", "")
        if not cmd.startswith("go to "):
            return raw_response
        # Only fire once per episode, and only after some progress has been
        # made (step_count > 1) so the task stays clearly solvable.
        if env_state.extras.get("injected"):
            return raw_response
        if env_state.step_count <= 1:
            return raw_response
        env_state.extras["injected"] = True
        # Rewrite the result payload to simulate an ineffective action.
        result = raw_response.info.get("result")
        if isinstance(result, dict):
            new_result = dict(result)
            new_result["result"] = "Nothing happens."
            new_info = {**raw_response.info, "result": new_result}
        else:
            new_info = {**raw_response.info, "result": {"result": "Nothing happens."}}
        return EnvResponse(
            observation=Observation(
                text="Nothing happens.",
                data=raw_response.observation.data,
            ),
            reward=raw_response.reward,
            terminated=raw_response.terminated,
            truncated=raw_response.truncated,
            info=new_info,
        )

