class _Rules(Rules):
    def filter_observation(self, obs, env_state):
        # Occasionally strip admissible_commands from the observation data
        # to force the Policy to reason about valid actions from context.
        # Only do this when the episode is still solvable (not done/won).
        if env_state.done or env_state.won:
            return obs
        # Drop only when the step count is in a "middle" range to avoid
        # breaking the opening or the final move.
        if env_state.step_count % 3 == 0:
            new_data = {k: v for k, v in obs.data.items() if k != "admissible_commands"}
            return Observation(text=obs.text, data=new_data)
        return obs
